RRB.load({"id": "ntpc-full-10", "exam": "ntpc", "label": "NTPC UG full mock 10 (100 Q)", "questions": [{"s": "General Awareness", "t": "History", "q": "Mangal Pandey attacked British officers in March 1857 at:", "o": ["Meerut", "Kanpur", "Barrackpore", "Lucknow"], "a": 2, "e": "Mangal Pandey of the 34th Bengal Native Infantry revolted at Barrackpore on 29 March 1857; the general outbreak began at Meerut on 10 May.", "qh": "मंगल पांडे ने मार्च 1857 में अंग्रेज़ अफ़सरों पर कहाँ हमला किया?", "oh": ["मेरठ", "कानपुर", "बैरकपुर", "लखनऊ"], "eh": "34वीं बंगाल नेटिव इन्फ़ैंट्री के मंगल पांडे ने 29 मार्च 1857 को बैरकपुर में विद्रोह किया; बड़ा विद्रोह 10 मई को मेरठ से शुरू हुआ।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "The 'Din-i-Ilahi' was started by which Mughal emperor?", "o": ["Akbar", "Jahangir", "Shah Jahan", "Aurangzeb"], "a": 0, "e": "Akbar started the Din-i-Ilahi (Tauhid-i-Ilahi) in 1582.", "qh": "'दीन-ए-इलाही' किस मुग़ल बादशाह ने शुरू किया?", "oh": ["अकबर", "जहाँगीर", "शाहजहाँ", "औरंगज़ेब"], "eh": "अकबर ने 1582 में दीन-ए-इलाही (तौहीद-ए-इलाही) शुरू किया।", "level": "easy"}, {"s": "General Awareness", "t": "Economy", "q": "The 'Startup India' initiative was launched in:", "o": ["2014", "2018", "2016", "2020"], "a": 2, "e": "Startup India was launched on 16 January 2016; 16 January is now National Startup Day.", "qh": "'स्टार्टअप इंडिया' पहल कब शुरू हुई?", "oh": ["2014", "2018", "2016", "2020"], "eh": "स्टार्टअप इंडिया 16 जनवरी 2016 को शुरू हुआ; 16 जनवरी अब राष्ट्रीय स्टार्टअप दिवस है।", "level": "medium"}, {"s": "General Awareness", "t": "Static GK", "q": "The 'Arthashastra' was written by:", "o": ["Kalidasa", "Banabhatta", "Kautilya (Chanakya)", "Vishakhadatta"], "a": 2, "e": "Kautilya's Arthashastra is an ancient treatise on statecraft and economy.", "qh": "'अर्थशास्त्र' किसने लिखा?", "oh": ["कालिदास", "बाणभट्ट", "कौटिल्य (चाणक्य)", "विशाखदत्त"], "eh": "कौटिल्य का अर्थशास्त्र राज्य-व्यवस्था और अर्थव्यवस्था पर एक प्राचीन ग्रंथ है।", "level": "easy"}, {"s": "General Awareness", "t": "Polity", "q": "The 'Objectives Resolution' in the Constituent Assembly (13 December 1946) was moved by:", "o": ["B. R. Ambedkar", "Rajendra Prasad", "Vallabhbhai Patel", "Jawaharlal Nehru"], "a": 3, "e": "Nehru's Objectives Resolution later became the basis of the Preamble.", "qh": "संविधान सभा में 'उद्देश्य प्रस्ताव' (13 दिसंबर 1946) किसने रखा?", "oh": ["बी. आर. आंबेडकर", "राजेंद्र प्रसाद", "वल्लभभाई पटेल", "जवाहरलाल नेहरू"], "eh": "नेहरू का उद्देश्य प्रस्ताव बाद में प्रस्तावना का आधार बना।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "The Great Rann of Kutch in Gujarat is best described as a:", "o": ["Freshwater lake", "Seasonal salt marsh", "Coral island", "Mangrove delta"], "a": 1, "e": "The Rann floods in the monsoon and dries into a white salt desert in winter.", "qh": "गुजरात के कच्छ के बड़े रण का सबसे सही वर्णन क्या है?", "oh": ["मीठे पानी की झील", "मौसमी नमकीन दलदल", "प्रवाल द्वीप", "मैंग्रोव डेल्टा"], "eh": "रण मानसून में पानी से भर जाता है और सर्दियों में सूखकर सफ़ेद नमक का रेगिस्तान बन जाता है।", "level": "medium"}, {"s": "General Awareness", "t": "Computer", "q": "A Solid State Drive (SSD) stores data on:", "o": ["Spinning magnetic platters", "Flash memory chips with no moving parts", "Optical discs read by a laser", "Magnetic tape reels"], "a": 1, "e": "SSDs use NAND flash memory, so they are faster and quieter than hard disks, which use spinning platters.", "qh": "सॉलिड स्टेट ड्राइव (SSD) डेटा किस पर रखती है?", "oh": ["घूमती चुंबकीय प्लेटें", "बिना चलने वाले पुर्ज़ों के फ़्लैश मेमोरी चिप", "लेज़र से पढ़ी जाने वाली ऑप्टिकल डिस्क", "चुंबकीय टेप की रीलें"], "eh": "SSD में NAND फ़्लैश मेमोरी होती है, इसलिए यह घूमती प्लेटों वाली हार्ड डिस्क से तेज़ और शांत होती है।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "A lactometer is used to test the:", "o": ["Purity (density) of milk", "Humidity of air", "Pressure of gas", "Speed of wind"], "a": 0, "e": "A lactometer measures milk density to detect added water.", "qh": "लैक्टोमीटर से क्या जाँचा जाता है?", "oh": ["दूध की शुद्धता (घनत्व)", "हवा की नमी", "गैस का दाब", "हवा की गति"], "eh": "लैक्टोमीटर दूध का घनत्व मापकर मिलाए गए पानी का पता लगाता है।", "level": "easy"}, {"s": "General Awareness", "t": "Sports", "q": "The Ranji Trophy is India's premier domestic tournament in:", "o": ["Football", "Cricket", "Hockey", "Kabaddi"], "a": 1, "e": "The Ranji Trophy, named after K. S. Ranjitsinhji, is the first-class cricket championship.", "qh": "रणजी ट्रॉफ़ी भारत का किस खेल का प्रमुख घरेलू टूर्नामेंट है?", "oh": ["फ़ुटबॉल", "क्रिकेट", "हॉकी", "कबड्डी"], "eh": "के. एस. रणजीतसिंहजी के नाम पर रखी गई रणजी ट्रॉफ़ी प्रथम श्रेणी क्रिकेट चैंपियनशिप है।", "level": "easy"}, {"s": "General Awareness", "t": "Awards", "q": "The 2026 Pulitzer Prize for Fiction was won by Daniel Kraus for which novel?", "o": ["Angel Down", "The Overstory", "James", "Demon Copperhead"], "a": 0, "e": "Daniel Kraus won the 2026 fiction Pulitzer for 'Angel Down'. (James – 2025, Demon Copperhead – 2023, The Overstory – 2019.)", "qh": "2026 का कथा साहित्य (फ़िक्शन) पुलित्ज़र पुरस्कार डेनियल क्राउस को किस उपन्यास के लिए मिला?", "oh": ["एंजल डाउन", "द ओवरस्टोरी", "जेम्स", "डेमन कॉपरहेड"], "eh": "डेनियल क्राउस को 'एंजल डाउन' के लिए 2026 का फ़िक्शन पुलित्ज़र मिला। (जेम्स – 2025, डेमन कॉपरहेड – 2023, द ओवरस्टोरी – 2019।)", "level": "tough"}, {"s": "General Awareness", "t": "Polity", "q": "Freedom of conscience and the right to freely profess, practise and propagate religion is given in:", "o": ["Article 19", "Article 29", "Article 30", "Article 25"], "a": 3, "e": "Article 25 guarantees freedom of conscience and religion, subject to public order, morality and health.", "qh": "अंतरात्मा की स्वतंत्रता और धर्म को मानने, आचरण करने और प्रचार करने का अधिकार किस अनुच्छेद में है?", "oh": ["अनुच्छेद 19", "अनुच्छेद 29", "अनुच्छेद 30", "अनुच्छेद 25"], "eh": "अनुच्छेद 25 सार्वजनिक व्यवस्था, सदाचार और स्वास्थ्य के अधीन अंतरात्मा और धर्म की स्वतंत्रता देता है।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "Which Chalukya king defeated Harshavardhana on the banks of the Narmada?", "o": ["Pulakeshin II", "Vikramaditya VI", "Kirtivarman I", "Mangalesha"], "a": 0, "e": "Pulakeshin II of Badami stopped Harsha's southward advance; the Aihole inscription by Ravikirti records it.", "qh": "किस चालुक्य राजा ने नर्मदा के किनारे हर्षवर्धन को हराया?", "oh": ["पुलकेशिन द्वितीय", "विक्रमादित्य षष्ठ", "कीर्तिवर्मन प्रथम", "मंगलेश"], "eh": "बादामी के पुलकेशिन द्वितीय ने हर्ष को दक्षिण की ओर बढ़ने से रोका; रविकीर्ति के ऐहोल अभिलेख में इसका वर्णन है।", "level": "medium"}, {"s": "General Awareness", "t": "General Science", "q": "In a hydroelectric power station, which energy change takes place?", "o": ["Chemical energy to electrical energy", "Nuclear energy to heat energy", "Light energy to electrical energy", "Potential energy of water to electrical energy"], "a": 3, "e": "Water stored at height falls on turbines; its potential energy becomes kinetic and then electrical energy.", "qh": "पनबिजली घर में कौन-सा ऊर्जा परिवर्तन होता है?", "oh": ["रासायनिक ऊर्जा से विद्युत ऊर्जा", "नाभिकीय ऊर्जा से ऊष्मा ऊर्जा", "प्रकाश ऊर्जा से विद्युत ऊर्जा", "पानी की स्थितिज ऊर्जा से विद्युत ऊर्जा"], "eh": "ऊँचाई पर जमा पानी टर्बाइन पर गिरता है; उसकी स्थितिज ऊर्जा गतिज और फिर विद्युत ऊर्जा बनती है।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "Subhas Chandra Bose founded the Forward Bloc in:", "o": ["1942", "1930", "1939", "1945"], "a": 2, "e": "Bose formed the All India Forward Bloc in 1939 after resigning as Congress President.", "qh": "सुभाष चंद्र बोस ने फ़ॉरवर्ड ब्लॉक की स्थापना कब की?", "oh": ["1942", "1930", "1939", "1945"], "eh": "बोस ने कांग्रेस अध्यक्ष पद से इस्तीफ़े के बाद 1939 में ऑल इंडिया फ़ॉरवर्ड ब्लॉक बनाया।", "level": "easy"}, {"s": "General Awareness", "t": "Polity", "q": "According to Article 79, the Parliament of India consists of:", "o": ["The Lok Sabha and the Rajya Sabha only", "The Lok Sabha, the Rajya Sabha and the Vice-President", "The Prime Minister and the two Houses", "The President, the Lok Sabha and the Rajya Sabha"], "a": 3, "e": "Article 79: Parliament consists of the President and two Houses – the Council of States and the House of the People.", "qh": "अनुच्छेद 79 के अनुसार भारत की संसद में कौन शामिल हैं?", "oh": ["केवल लोकसभा और राज्यसभा", "लोकसभा, राज्यसभा और उपराष्ट्रपति", "प्रधानमंत्री और दोनों सदन", "राष्ट्रपति, लोकसभा और राज्यसभा"], "eh": "अनुच्छेद 79: संसद राष्ट्रपति और दो सदनों – राज्यसभा और लोकसभा – से बनती है।", "level": "tough"}, {"s": "General Awareness", "t": "History", "q": "The Hathigumpha inscription near Bhubaneswar describes the achievements of:", "o": ["Ashoka", "Samudragupta", "Kharavela", "Rudradaman"], "a": 2, "e": "The Hathigumpha inscription in the Udayagiri caves records the reign of Kharavela, king of Kalinga.", "qh": "भुवनेश्वर के पास हाथीगुम्फा अभिलेख किसकी उपलब्धियों का वर्णन करता है?", "oh": ["अशोक", "समुद्रगुप्त", "खारवेल", "रुद्रदामन"], "eh": "उदयगिरि गुफ़ाओं का हाथीगुम्फा अभिलेख कलिंग के राजा खारवेल के शासन का वर्णन करता है।", "level": "tough"}, {"s": "General Awareness", "t": "Railways", "q": "Bilaspur (Chhattisgarh) is the headquarters of which railway zone?", "o": ["South Eastern Railway", "West Central Railway", "East Coast Railway", "South East Central Railway"], "a": 3, "e": "SECR is at Bilaspur; South Eastern – Kolkata (Garden Reach), West Central – Jabalpur, East Coast – Bhubaneswar.", "qh": "बिलासपुर (छत्तीसगढ़) किस रेलवे ज़ोन का मुख्यालय है?", "oh": ["दक्षिण पूर्व रेलवे", "पश्चिम मध्य रेलवे", "पूर्व तटीय रेलवे", "दक्षिण पूर्व मध्य रेलवे"], "eh": "SECR बिलासपुर में है; दक्षिण पूर्व – कोलकाता (गार्डन रीच), पश्चिम मध्य – जबलपुर, पूर्व तटीय – भुवनेश्वर।", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "In August 2026, UPI set a new monthly record of about how many transactions?", "o": ["24.5 billion", "18.4 billion", "12.0 billion", "30.2 billion"], "a": 0, "e": "NPCI data showed a record 24.51 billion UPI transactions in August 2026.", "qh": "अगस्त 2026 में UPI ने लगभग कितने लेन-देन का नया मासिक रिकॉर्ड बनाया?", "oh": ["24.5 अरब", "18.4 अरब", "12.0 अरब", "30.2 अरब"], "eh": "NPCI के आँकड़ों के अनुसार अगस्त 2026 में रिकॉर्ड 24.51 अरब UPI लेन-देन हुए।", "level": "tough"}, {"s": "General Awareness", "t": "General Science", "q": "Which law states that, at constant temperature, the volume of a fixed mass of gas is inversely proportional to its pressure?", "o": ["Charles's law", "Avogadro's law", "Graham's law", "Boyle's law"], "a": 3, "e": "Boyle's law: PV = constant at fixed temperature. Charles's law relates volume and temperature.", "qh": "किस नियम के अनुसार स्थिर ताप पर किसी गैस के निश्चित द्रव्यमान का आयतन उसके दाब के व्युत्क्रमानुपाती होता है?", "oh": ["चार्ल्स का नियम", "आवोगाद्रो का नियम", "ग्राहम का नियम", "बॉयल का नियम"], "eh": "बॉयल का नियम: स्थिर ताप पर PV = स्थिरांक। चार्ल्स का नियम आयतन और ताप को जोड़ता है।", "level": "tough"}, {"s": "General Awareness", "t": "Current Affairs", "q": "Who was sworn in as the President of Myanmar in April 2026?", "o": ["Aung San Suu Kyi", "Win Myint", "Min Aung Hlaing", "Myint Swe"], "a": 2, "e": "Military chief Min Aung Hlaing was sworn in as President on 10 April 2026 after a parliamentary vote.", "qh": "अप्रैल 2026 में म्यांमार के राष्ट्रपति पद की शपथ किसने ली?", "oh": ["आंग सान सू की", "विन म्यिंट", "मिन आंग ह्लाइंग", "म्यिंट स्वे"], "eh": "सेना प्रमुख मिन आंग ह्लाइंग ने संसद में मतदान के बाद 10 अप्रैल 2026 को राष्ट्रपति पद की शपथ ली।", "level": "medium"}, {"s": "General Awareness", "t": "Computer", "q": "In most web browsers, which key reloads (refreshes) the current page?", "o": ["F5", "F1", "F2", "F12"], "a": 0, "e": "F5 refreshes the page; F1 usually opens Help and F12 opens developer tools.", "qh": "ज़्यादातर वेब ब्राउज़रों में कौन-सी कुंजी मौजूदा पेज को फिर से लोड (रिफ़्रेश) करती है?", "oh": ["F5", "F1", "F2", "F12"], "eh": "F5 पेज रिफ़्रेश करती है; F1 आम तौर पर हेल्प खोलती है और F12 डेवलपर टूल।", "level": "easy"}, {"s": "General Awareness", "t": "Economy", "q": "The 'Yellow Revolution' is related to the production of:", "o": ["Eggs", "Honey", "Oilseeds", "Pulses"], "a": 2, "e": "The Yellow Revolution (from 1986, Technology Mission on Oilseeds) boosted oilseed output.", "qh": "'पीली क्रांति' किसके उत्पादन से जुड़ी है?", "oh": ["अंडे", "शहद", "तिलहन", "दालें"], "eh": "पीली क्रांति (1986 से, तिलहन प्रौद्योगिकी मिशन) ने तिलहन उत्पादन बढ़ाया।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "'El Niño' refers to:", "o": ["Cooling of the Arabian Sea", "A cold wind blowing over north India", "Unusual warming of sea surface waters in the central and eastern Pacific", "A cyclone in the Bay of Bengal"], "a": 2, "e": "El Niño warms the eastern Pacific and is often linked with a weaker Indian monsoon.", "qh": "'अल नीनो' किसे कहते हैं?", "oh": ["अरब सागर का ठंडा होना", "उत्तर भारत में चलने वाली ठंडी हवा", "मध्य और पूर्वी प्रशांत महासागर की सतह के पानी का असामान्य रूप से गर्म होना", "बंगाल की खाड़ी का चक्रवात"], "eh": "अल नीनो पूर्वी प्रशांत को गर्म करता है और अक्सर कमज़ोर भारतीय मानसून से जुड़ा होता है।", "level": "tough"}, {"s": "General Awareness", "t": "Sports", "q": "At the 2026 FIFA World Cup, Kylian Mbappé became the first player to:", "o": ["Win the Golden Boot at two World Cups", "Score in four World Cup finals", "Captain two title-winning teams", "Score a hat-trick in two finals"], "a": 0, "e": "Mbappé won the Golden Boot again with 10 goals, the first player to win it twice. The 2026 World Cup was held in the USA, Canada and Mexico (11 June–19 July 2026); Spain beat Argentina in the final. India did not qualify.", "qh": "2026 फ़ीफ़ा विश्व कप में किलियन एम्बाप्पे ऐसा करने वाले पहले खिलाड़ी बने:", "oh": ["दो विश्व कपों में गोल्डन बूट जीतना", "चार विश्व कप फ़ाइनल में गोल करना", "दो विजेता टीमों की कप्तानी करना", "दो फ़ाइनल में हैट्रिक लगाना"], "eh": "एम्बाप्पे ने 10 गोल के साथ फिर गोल्डन बूट जीता और इसे दो बार जीतने वाले पहले खिलाड़ी बने। 2026 विश्व कप अमेरिका, कनाडा और मेक्सिको में (11 जून–19 जुलाई 2026) हुआ; फ़ाइनल में स्पेन ने अर्जेंटीना को हराया। भारत क्वालिफ़ाई नहीं कर पाया।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Periyar Tiger Reserve (Thekkady) is in which state?", "o": ["Tamil Nadu", "Karnataka", "Goa", "Kerala"], "a": 3, "e": "Periyar Tiger Reserve lies around the Periyar lake in Idukki district, Kerala.", "qh": "पेरियार बाघ अभयारण्य (थेक्कडी) किस राज्य में है?", "oh": ["तमिलनाडु", "कर्नाटक", "गोवा", "केरल"], "eh": "पेरियार बाघ अभयारण्य केरल के इडुक्की ज़िले में पेरियार झील के आसपास है।", "level": "medium"}, {"s": "General Awareness", "t": "Science & Tech", "q": "'Param2', unveiled at the India AI Impact Summit in February 2026, is:", "o": ["A new supercomputer built by C-DAC", "An earth-observation satellite of ISRO", "A hypersonic missile of DRDO", "A multilingual AI foundation model built by BharatGen"], "a": 3, "e": "BharatGen launched Param2, a 17-billion-parameter multilingual mixture-of-experts language model. (C-DAC's 'PARAM' is a separate supercomputer series.)", "qh": "फ़रवरी 2026 के इंडिया AI इम्पैक्ट समिट में पेश किया गया 'Param2' क्या है?", "oh": ["C-DAC का नया सुपरकंप्यूटर", "ISRO का पृथ्वी-अवलोकन उपग्रह", "DRDO की हाइपरसोनिक मिसाइल", "BharatGen द्वारा बनाया गया बहुभाषी AI फ़ाउंडेशन मॉडल"], "eh": "BharatGen ने Param2 पेश किया, जो 17 अरब पैरामीटर वाला बहुभाषी मिक्सचर-ऑफ़-एक्सपर्ट्स भाषा मॉडल है। (C-DAC की 'PARAM' अलग सुपरकंप्यूटर शृंखला है।)", "level": "tough"}, {"s": "General Awareness", "t": "Static GK", "q": "National Statistics Day (29 June) honours the birth anniversary of:", "o": ["P. C. Mahalanobis", "C. R. Rao", "Srinivasa Ramanujan", "M. Visvesvaraya"], "a": 0, "e": "P. C. Mahalanobis, founder of the Indian Statistical Institute, was born on 29 June 1893.", "qh": "राष्ट्रीय सांख्यिकी दिवस (29 जून) किसकी जयंती पर मनाया जाता है?", "oh": ["पी. सी. महालनोबिस", "सी. आर. राव", "श्रीनिवास रामानुजन", "एम. विश्वेश्वरैया"], "eh": "भारतीय सांख्यिकी संस्थान के संस्थापक पी. सी. महालनोबिस का जन्म 29 जून 1893 को हुआ था।", "level": "medium"}, {"s": "General Awareness", "t": "Art & Culture", "q": "Chapchar Kut, a spring festival celebrated after clearing the jungle for jhum cultivation, belongs to:", "o": ["Mizoram", "Nagaland", "Meghalaya", "Tripura"], "a": 0, "e": "Chapchar Kut is Mizoram's main spring festival, held in March.", "qh": "झूम खेती के लिए जंगल साफ़ करने के बाद मनाया जाने वाला वसंत उत्सव चापचार कुट किस राज्य का है?", "oh": ["मिज़ोरम", "नागालैंड", "मेघालय", "त्रिपुरा"], "eh": "चापचार कुट मार्च में मनाया जाने वाला मिज़ोरम का मुख्य वसंत उत्सव है।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Bomdila pass is in which state?", "o": ["Sikkim", "Himachal Pradesh", "Uttarakhand", "Arunachal Pradesh"], "a": 3, "e": "Bomdila (West Kameng district) links Arunachal Pradesh with Lhasa in Tibet.", "qh": "बोमडिला दर्रा किस राज्य में है?", "oh": ["सिक्किम", "हिमाचल प्रदेश", "उत्तराखंड", "अरुणाचल प्रदेश"], "eh": "बोमडिला (पश्चिम कामेंग ज़िला) अरुणाचल प्रदेश को तिब्बत के ल्हासा से जोड़ता है।", "level": "medium"}, {"s": "General Awareness", "t": "Science & Tech", "q": "The Satish Dhawan Space Centre, India's main rocket launch site, is at:", "o": ["Thumba, Kerala", "Chandipur, Odisha", "Mahendragiri, Tamil Nadu", "Sriharikota, Andhra Pradesh"], "a": 3, "e": "SDSC-SHAR at Sriharikota (Tirupati district) launches PSLV, GSLV and LVM3. Mahendragiri tests engines.", "qh": "भारत का मुख्य रॉकेट प्रक्षेपण केंद्र सतीश धवन अंतरिक्ष केंद्र कहाँ है?", "oh": ["थुंबा, केरल", "चांदीपुर, ओडिशा", "महेंद्रगिरि, तमिलनाडु", "श्रीहरिकोटा, आंध्र प्रदेश"], "eh": "श्रीहरिकोटा (तिरुपति ज़िला) का SDSC-SHAR PSLV, GSLV और LVM3 छोड़ता है। महेंद्रगिरि में इंजनों का परीक्षण होता है।", "level": "medium"}, {"s": "General Awareness", "t": "Economy", "q": "Gross National Product (GNP) is equal to:", "o": ["GDP − depreciation", "GDP + net factor income from abroad", "GDP + indirect taxes", "GDP − subsidies"], "a": 1, "e": "GNP adds net income earned by residents from abroad to GDP; GDP − depreciation gives NDP.", "qh": "सकल राष्ट्रीय उत्पाद (GNP) किसके बराबर है?", "oh": ["GDP − मूल्यह्रास", "GDP + विदेश से शुद्ध साधन आय", "GDP + अप्रत्यक्ष कर", "GDP − सब्सिडी"], "eh": "GNP में GDP के साथ निवासियों की विदेश से शुद्ध आय जोड़ी जाती है; GDP − मूल्यह्रास = NDP।", "level": "tough"}, {"s": "General Awareness", "t": "Art & Culture", "q": "Kalighat painting, known for bold lines and everyday themes, developed in:", "o": ["Madhubani (Bihar)", "Puri (Odisha)", "Nathdwara (Rajasthan)", "Kolkata (West Bengal)"], "a": 3, "e": "Kalighat pat paintings were made near the Kalighat Kali temple in 19th-century Calcutta.", "qh": "मोटी रेखाओं और रोज़मर्रा के विषयों वाली कालीघाट चित्रकला कहाँ विकसित हुई?", "oh": ["मधुबनी (बिहार)", "पुरी (ओडिशा)", "नाथद्वारा (राजस्थान)", "कोलकाता (पश्चिम बंगाल)"], "eh": "कालीघाट पट चित्र 19वीं सदी के कलकत्ता में कालीघाट काली मंदिर के पास बनाए जाते थे।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "Who was the first Lokpal (chairperson) of India, appointed in 2019?", "o": ["Justice Ranjana Desai", "Justice Pinaki Chandra Ghose", "Justice A. K. Patnaik", "Justice J. S. Khehar"], "a": 1, "e": "Justice P. C. Ghose, a former Supreme Court judge, was appointed the first Lokpal in March 2019.", "qh": "2019 में नियुक्त भारत के पहले लोकपाल (अध्यक्ष) कौन थे?", "oh": ["न्यायमूर्ति रंजना देसाई", "न्यायमूर्ति पिनाकी चंद्र घोष", "न्यायमूर्ति ए. के. पटनायक", "न्यायमूर्ति जे. एस. खेहर"], "eh": "सर्वोच्च न्यायालय के पूर्व न्यायाधीश न्यायमूर्ति पी. सी. घोष मार्च 2019 में पहले लोकपाल बने।", "level": "medium"}, {"s": "General Awareness", "t": "History", "q": "Which document is called the 'Magna Carta of English education in India'?", "o": ["Macaulay's Minute, 1835", "Hunter Commission report, 1882", "Wood's Despatch, 1854", "Sadler Commission report, 1919"], "a": 2, "e": "Charles Wood's Despatch (1854) laid out a full education system from primary schools to universities.", "qh": "किस दस्तावेज़ को 'भारत में अंग्रेज़ी शिक्षा का मैग्ना कार्टा' कहा जाता है?", "oh": ["मैकॉले का मिनट, 1835", "हंटर आयोग रिपोर्ट, 1882", "वुड्स डिस्पैच, 1854", "सैडलर आयोग रिपोर्ट, 1919"], "eh": "चार्ल्स वुड के डिस्पैच (1854) ने प्राथमिक स्कूल से विश्वविद्यालय तक पूरी शिक्षा व्यवस्था की रूपरेखा दी।", "level": "tough"}, {"s": "General Awareness", "t": "General Science", "q": "Stainless steel is an alloy of iron mainly with:", "o": ["Chromium (and nickel)", "Copper and zinc", "Tin and lead", "Aluminium and magnesium"], "a": 0, "e": "Chromium (at least about 10.5%) forms a protective oxide layer that resists rusting.", "qh": "स्टेनलेस स्टील मुख्य रूप से लोहे की किसके साथ मिश्रधातु है?", "oh": ["क्रोमियम (और निकल)", "तांबा और जस्ता", "टिन और सीसा", "एल्युमिनियम और मैग्नीशियम"], "eh": "क्रोमियम (कम से कम लगभग 10.5%) एक सुरक्षात्मक ऑक्साइड परत बनाता है जो जंग से बचाती है।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "The three-tier Panchayati Raj system was first recommended by the:", "o": ["Ashok Mehta Committee (1977)", "Balwant Rai Mehta Committee (1957)", "L. M. Singhvi Committee (1986)", "G. V. K. Rao Committee (1985)"], "a": 1, "e": "The Balwant Rai Mehta Committee proposed village, block and district bodies; Rajasthan (Nagaur, 1959) was first to adopt it.", "qh": "त्रिस्तरीय पंचायती राज व्यवस्था की सिफ़ारिश सबसे पहले किसने की?", "oh": ["अशोक मेहता समिति (1977)", "बलवंत राय मेहता समिति (1957)", "एल. एम. सिंघवी समिति (1986)", "जी. वी. के. राव समिति (1985)"], "eh": "बलवंत राय मेहता समिति ने ग्राम, प्रखंड और ज़िला स्तर के निकाय सुझाए; राजस्थान (नागौर, 1959) ने इसे सबसे पहले अपनाया।", "level": "tough"}, {"s": "General Awareness", "t": "Awards", "q": "The Nobel Prize in Physics 2026 went to Francis Halzen for his work on the IceCube observatory, which detects:", "o": ["Gravitational waves", "Dark matter particles", "Exoplanets", "High-energy neutrinos from space"], "a": 3, "e": "Halzen led IceCube, a cubic kilometre of instrumented ice at the South Pole that discovered high-energy neutrinos of astrophysical origin.", "qh": "भौतिकी का नोबेल पुरस्कार 2026 फ़्रांसिस हाल्ज़ेन को आइसक्यूब वेधशाला पर काम के लिए मिला, जो क्या पकड़ती है?", "oh": ["गुरुत्वीय तरंगें", "डार्क मैटर कण", "बाह्य ग्रह", "अंतरिक्ष से आने वाले उच्च-ऊर्जा न्यूट्रिनो"], "eh": "हाल्ज़ेन ने आइसक्यूब का नेतृत्व किया, जो दक्षिणी ध्रुव पर सेंसर लगी एक घन किलोमीटर बर्फ़ है और जिसने खगोलीय स्रोतों से आने वाले उच्च-ऊर्जा न्यूट्रिनो खोजे।", "level": "medium"}, {"s": "General Awareness", "t": "Geography", "q": "Dal Lake is located in:", "o": ["Srinagar", "Shimla", "Nainital", "Udaipur"], "a": 0, "e": "Dal Lake in Srinagar, Jammu and Kashmir, is known for its houseboats and shikaras.", "qh": "डल झील कहाँ है?", "oh": ["श्रीनगर", "शिमला", "नैनीताल", "उदयपुर"], "eh": "जम्मू-कश्मीर के श्रीनगर की डल झील हाउसबोट और शिकारों के लिए जानी जाती है।", "level": "easy"}, {"s": "General Awareness", "t": "Geography", "q": "The Kolar Gold Fields are in which state?", "o": ["Karnataka", "Jharkhand", "Andhra Pradesh", "Rajasthan"], "a": 0, "e": "Kolar Gold Fields in Karnataka were among the deepest gold mines in the world; they closed in 2001.", "qh": "कोलार स्वर्ण क्षेत्र किस राज्य में है?", "oh": ["कर्नाटक", "झारखंड", "आंध्र प्रदेश", "राजस्थान"], "eh": "कर्नाटक के कोलार स्वर्ण क्षेत्र दुनिया की सबसे गहरी सोने की खदानों में थे; ये 2001 में बंद हुए।", "level": "medium"}, {"s": "General Awareness", "t": "Polity", "q": "The Ninth Schedule, which protects certain laws from judicial review, was added by the:", "o": ["7th Amendment, 1956", "24th Amendment, 1971", "1st Amendment, 1951", "42nd Amendment, 1976"], "a": 2, "e": "The First Amendment (1951) added the Ninth Schedule to protect land-reform laws.", "qh": "कुछ कानूनों को न्यायिक समीक्षा से बचाने वाली नौवीं अनुसूची किस संशोधन से जोड़ी गई?", "oh": ["7वाँ संशोधन, 1956", "24वाँ संशोधन, 1971", "पहला संशोधन, 1951", "42वाँ संशोधन, 1976"], "eh": "पहले संशोधन (1951) ने भूमि सुधार कानूनों को बचाने के लिए नौवीं अनुसूची जोड़ी।", "level": "tough"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "What is the range of the data: 40, 9, 32, 41, 33, 41, 15, 41, 35, 56, 11, 9?", "o": ["65", "56", "49", "47"], "a": 3, "e": "Range = highest − lowest = 56 − 9 = 47.", "qh": "आँकड़ों 40, 9, 32, 41, 33, 41, 15, 41, 35, 56, 11, 9 का परिसर (range) क्या है?", "oh": ["65", "56", "49", "47"], "eh": "परिसर = सबसे बड़ा − सबसे छोटा = 56 − 9 = 47।", "level": "tough"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "What is the third proportional to 9 and 27?", "o": ["162", "81", "83", "78"], "a": 1, "e": "9 : 27 = 27 : x → x = 27²/9 = 729/9 = 81.", "qh": "9 और 27 का तीसरा समानुपाती क्या है?", "oh": ["162", "81", "83", "78"], "eh": "9 : 27 = 27 : x → x = 27²/9 = 729/9 = 81।", "level": "medium"}, {"s": "Mathematics", "t": "Percentage", "q": "Karan's salary is 50% more than Pooja's salary. By what percentage is Pooja's salary less than Karan's?", "o": ["33 1/3%", "38 1/3%", "25%", "50%"], "a": 0, "e": "Take Pooja = 100, Karan = 150. Less by 50/150 × 100 = 33 1/3%.", "qh": "करण की तनख्वाह पूजा की तनख्वाह से 50% ज़्यादा है। पूजा की तनख्वाह करण की तनख्वाह से कितने प्रतिशत कम है?", "oh": ["33 1/3%", "38 1/3%", "25%", "50%"], "eh": "पूजा = 100 मानें, करण = 150। कम = 50/150 × 100 = 33 1/3%।", "level": "easy"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "A car covers 160 km in 3 hours 20 minutes. What is its speed in metres per second?", "o": ["40/3 m/s", "80/3 m/s", "55/3 m/s", "172.8 m/s"], "a": 0, "e": "Speed = 160/10/3 = 48 km/h = 48 × 5/18 = 40/3 m/s.", "qh": "एक कार 160 km की दूरी 3 घंटे 20 मिनट में तय करती है। उसकी रफ़्तार मीटर प्रति सेकंड में कितनी है?", "oh": ["40/3 m/s", "80/3 m/s", "55/3 m/s", "172.8 m/s"], "eh": "रफ़्तार = 160/10/3 = 48 km/h = 48 × 5/18 = 40/3 m/s।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "A 40-litre mixture contains acid and water in the ratio 7 : 3. How many litres of water must be added to make the ratio 2 : 1?", "o": ["4 litres", "2 litres", "40/3 litres", "7 litres"], "a": 1, "e": "Acid = 28 L, water = 12 L. Need 28 : (12 + x) = 2 : 1 → x = 28×1/2 − 12 = 2 L.", "qh": "40 लीटर के एक मिश्रण में अम्ल और पानी का अनुपात 7 : 3 है। अनुपात 2 : 1 करने के लिए इसमें कितने लीटर पानी मिलाना होगा?", "oh": ["4 litres", "2 litres", "40/3 litres", "7 litres"], "eh": "अम्ल = 28 L, पानी = 12 L। 28 : (12 + x) = 2 : 1 → x = 28×1/2 − 12 = 2 L।", "level": "easy"}, {"s": "Mathematics", "t": "Ages", "q": "The sum of the present ages of a mother and daughter is 40 years. 2 years ago, the mother's age was 3 times the daughter's age. What is the present age of the daughter?", "o": ["10 years", "9 years", "11 years", "29 years"], "a": 2, "e": "Let daughter = x. (40 − x − 2) = 3(x − 2) → 40 − 2 + 6 = 4x → x = 11 years.", "qh": "एक माँ और बेटी की वर्तमान आयु का योग 40 साल है। 2 साल पहले माँ की आयु बेटी की आयु की 3 गुनी थी। बेटी की वर्तमान आयु क्या है?", "oh": ["10 साल", "9 साल", "11 साल", "29 साल"], "eh": "माना बेटी की आयु = x। (40 − x − 2) = 3(x − 2) → 40 − 2 + 6 = 4x → x = 11 साल।", "level": "medium"}, {"s": "Mathematics", "t": "Time and Work", "q": "Pipes A and B can fill a tank in 20 hours and 30 hours, while pipe C can empty the full tank in 24 hours. If all three are opened together on an empty tank, in how many hours will it be full?", "o": ["23 hours", "24 hours", "14 hours", "25 hours"], "a": 1, "e": "Net per hour = 1/20 + 1/30 − 1/24 = 1/24 → 24 hours.", "qh": "पाइप A और B एक टंकी को 20 घंटे और 30 घंटे में भरते हैं, जबकि पाइप C भरी टंकी को 24 घंटे में खाली करता है। खाली टंकी पर तीनों एक साथ खोलने पर टंकी कितने घंटे में भरेगी?", "oh": ["23 घंटे", "24 घंटे", "14 घंटे", "25 घंटे"], "eh": "हर घंटे कुल भराई = 1/20 + 1/30 − 1/24 = 1/24 → 24 घंटे।", "level": "tough"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A vendor buys 10 bananas for ₹120 and sells 8 bananas for ₹90. What is his loss percentage?", "o": ["11.25%", "6.25%", "12.5%", "20%"], "a": 1, "e": "CP of 1 = 12, SP of 1 = 11.25. Loss % = |11.25 − 12|/12 × 100 = 6.25%.", "qh": "एक विक्रेता ₹120 में 10 केले खरीदता है और ₹90 में 8 केले बेचता है। उसका हानि प्रतिशत क्या है?", "oh": ["11.25%", "6.25%", "12.5%", "20%"], "eh": "1 केले का क्रय मूल्य = 12, विक्रय मूल्य = 11.25। प्रतिशत = |11.25 − 12|/12 × 100 = 6.25%।", "level": "medium"}, {"s": "Mathematics", "t": "Interest", "q": "A sum lent at simple interest becomes four times the principal after 16 years. Find the annual rate of interest.", "o": ["20.75%", "1 9/16%", "18.75%", "25%"], "a": 2, "e": "Interest = 3 × P = P × R × 16/100 → R = 300/16 = 18.75%.", "qh": "साधारण ब्याज पर दी गई एक राशि 16 साल बाद मूलधन की चार गुनी हो जाती है। वार्षिक ब्याज दर बताइए।", "oh": ["20.75%", "1 9/16%", "18.75%", "25%"], "eh": "ब्याज = 3 × P = P × R × 16/100 → R = 300/16 = 18.75%।", "level": "easy"}, {"s": "Mathematics", "t": "Interest", "q": "What is the difference between the compound interest and simple interest on ₹33,000 for 2 years at 20% per annum (compounded annually)?", "o": ["₹1,320", "₹6,600", "₹2,640", "₹1,330"], "a": 0, "e": "For 2 years, CI − SI = P(R/100)² = ₹33,000 × (20/100)² = ₹1,320.", "qh": "₹33,000 पर 20% वार्षिक दर से 2 साल के चक्रवृद्धि ब्याज (वार्षिक) और साधारण ब्याज का अंतर क्या है?", "oh": ["₹1,320", "₹6,600", "₹2,640", "₹1,330"], "eh": "2 साल के लिए CI − SI = P(R/100)² = ₹33,000 × (20/100)² = ₹1,320।", "level": "medium"}, {"s": "Mathematics", "t": "Number System", "q": "What is the unit digit of 17^47 × 12^85?", "o": ["2", "6", "8", "0"], "a": 1, "e": "Unit digit of 17^47 = 3, of 12^85 = 2. 3 × 2 → unit digit 6.", "qh": "17^47 × 12^85 का इकाई अंक क्या है?", "oh": ["2", "6", "8", "0"], "eh": "17^47 का इकाई अंक = 3, 12^85 का = 2। 3 × 2 → इकाई अंक 6।", "level": "tough"}, {"s": "Mathematics", "t": "Geometry", "q": "How many diagonals does a polygon with 18 sides have?", "o": ["153", "135", "132", "144"], "a": 1, "e": "Diagonals = n(n − 3)/2 = 18×15/2 = 135.", "qh": "18 भुजाओं वाले बहुभुज में कितने विकर्ण होते हैं?", "oh": ["153", "135", "132", "144"], "eh": "विकर्ण = n(n − 3)/2 = 18×15/2 = 135।", "level": "tough"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "Successive discounts of 30%, 10% and 10% are equivalent to a single discount of:", "o": ["44.3%", "49%", "43.3%", "50%"], "a": 2, "e": "Price left = 0.7 × 0.9 × 0.9 = 567/1000. Single discount = 43.3%.", "qh": "30%, 10% और 10% की लगातार छूट किस एक छूट के बराबर हैं?", "oh": ["44.3%", "49%", "43.3%", "50%"], "eh": "बचा दाम = 0.7 × 0.9 × 0.9 = 567/1000। एक छूट = 43.3%।", "level": "tough"}, {"s": "Mathematics", "t": "Mensuration", "q": "If each edge of a cube is made 2 times, by what percentage does its surface area increase?", "o": ["100%", "700%", "300%", "400%"], "a": 2, "e": "New area = 2² = 4 times → increase = (4 − 1) × 100 = 300%.", "qh": "अगर घन की हर भुजा 2 गुनी कर दी जाए, तो उसका पृष्ठीय क्षेत्रफल कितने प्रतिशत बढ़ेगा?", "oh": ["100%", "700%", "300%", "400%"], "eh": "नया क्षेत्रफल = 2² = 4 गुना → बढ़ोतरी = (4 − 1) × 100 = 300%।", "level": "medium"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: [18 + {17 × 4 − (16 + 2)}] ÷ 4 + 7", "o": ["26", "24", "48", "34"], "a": 1, "e": "Follow BODMAS (brackets, then ÷ and × from left to right, then + and −): value = 24.", "qh": "सरल कीजिए: [18 + {17 × 4 − (16 + 2)}] ÷ 4 + 7", "oh": ["26", "24", "48", "34"], "eh": "BODMAS के नियम से (पहले कोष्ठक, फिर बाएँ से दाएँ ÷ और ×, फिर + और −): मान = 24।", "level": "tough"}, {"s": "Mathematics", "t": "Algebra", "q": "A two-digit number has digits adding up to 13. Interchanging its digits increases the number by 9. Find the number.", "o": ["67", "94", "76", "49"], "a": 0, "e": "9(u − t) = 9 → u − t = 1; u + t = 13 → u = 7, t = 6; number = 67.", "qh": "दो अंकों की एक संख्या के अंकों का योग 13 है। अंकों की जगह बदलने से संख्या 9 बढ़ जाती है। संख्या बताइए।", "oh": ["67", "94", "76", "49"], "eh": "9(u − t) = 9 → u − t = 1; u + t = 13 → u = 7, t = 6; संख्या = 67।", "level": "easy"}, {"s": "Mathematics", "t": "Number System", "q": "What is the unit digit of 7^26?", "o": ["2", "9", "5", "0"], "a": 1, "e": "Unit digits of powers of 7 repeat as 7, 9, 3, 1 (cycle 4). 26 mod 4 = 2 → unit digit 9.", "qh": "7^26 का इकाई अंक क्या है?", "oh": ["2", "9", "5", "0"], "eh": "7 की घातों के इकाई अंक 7, 9, 3, 1 दोहराते हैं (चक्र 4)। 26 को 4 से भाग देने पर 2 → इकाई अंक 9।", "level": "easy"}, {"s": "Mathematics", "t": "Mensuration", "q": "A wheel of radius 35 cm makes 500 complete revolutions. What distance does it cover? (Take π = 22/7)", "o": ["1110 m", "2200 m", "550 m", "1100 m"], "a": 3, "e": "One revolution = 2πr = 220 cm; distance = 220 × 500 = 110000 cm = 1100 m.", "qh": "35 cm त्रिज्या वाला एक पहिया 500 पूरे चक्कर लगाता है। वह कितनी दूरी तय करता है? (π = 22/7 लें)", "oh": ["1110 m", "2200 m", "550 m", "1100 m"], "eh": "एक चक्कर = 2πr = 220 cm; दूरी = 220 × 500 = 110000 cm = 1100 m।", "level": "tough"}, {"s": "Mathematics", "t": "Number System", "q": "How many numbers from 300 to 900 are divisible by both 5 and 7?", "o": ["16", "34", "19", "17"], "a": 3, "e": "Divisible by both = divisible by LCM 35: ⌊900/35⌋ − ⌊299/35⌋ = 17.", "qh": "300 से 900 तक कितनी संख्याएँ 5 और 7 दोनों से विभाज्य हैं?", "oh": ["16", "34", "19", "17"], "eh": "दोनों से विभाज्य = LCM से विभाज्य 35: ⌊900/35⌋ − ⌊299/35⌋ = 17।", "level": "medium"}, {"s": "Mathematics", "t": "Speed, Time and Distance", "q": "Two buses start at the same time from Indore and Bhopal, 600 km apart, and travel towards each other at 50 km/h and 25 km/h. After how much time will they meet?", "o": ["8 hours", "7 h 30 min", "24 hours", "9 hours"], "a": 0, "e": "Relative speed = 50 + 25 = 75 km/h; time = 600/75 h = 8 hours.", "qh": "दो बसें एक साथ इंदौर और भोपाल से, जो 600 km दूर हैं, एक-दूसरे की ओर 50 km/h और 25 km/h की चाल से चलती हैं। कितने समय बाद वे मिलेंगी?", "oh": ["8 घंटे", "7 घंटे 30 मिनट", "24 घंटे", "9 घंटे"], "eh": "सापेक्ष चाल = 50 + 25 = 75 km/h; समय = 600/75 घंटे = 8 घंटे।", "level": "medium"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "A vendor buys 6 bananas for ₹50 and sells 5 bananas for ₹90. What is his profit percentage?", "o": ["232%", "121%", "116%", "16 2/3%"], "a": 2, "e": "CP of 1 = 25/3, SP of 1 = 18. Profit % = |18 − 25/3|/25/3 × 100 = 116%.", "qh": "एक विक्रेता ₹50 में 6 केले खरीदता है और ₹90 में 5 केले बेचता है। उसका लाभ प्रतिशत क्या है?", "oh": ["232%", "121%", "116%", "16 2/3%"], "eh": "1 केले का क्रय मूल्य = 25/3, विक्रय मूल्य = 18। प्रतिशत = |18 − 25/3|/25/3 × 100 = 116%।", "level": "tough"}, {"s": "Mathematics", "t": "Time and Work", "q": "Pipes A and B can fill a tank in 10 hours and 15 hours, while pipe C can empty the full tank in 30 hours. If all three are opened together on an empty tank, in how many hours will it be full?", "o": ["12.5 hours", "7.5 hours", "15 hours", "6.5 hours"], "a": 1, "e": "Net per hour = 1/10 + 1/15 − 1/30 = 2/15 → 7.5 hours.", "qh": "पाइप A और B एक टंकी को 10 घंटे और 15 घंटे में भरते हैं, जबकि पाइप C भरी टंकी को 30 घंटे में खाली करता है। खाली टंकी पर तीनों एक साथ खोलने पर टंकी कितने घंटे में भरेगी?", "oh": ["12.5 घंटे", "7.5 घंटे", "15 घंटे", "6.5 घंटे"], "eh": "हर घंटे कुल भराई = 1/10 + 1/15 − 1/30 = 2/15 → 7.5 घंटे।", "level": "medium"}, {"s": "Mathematics", "t": "Ratio and Proportion", "q": "A 50-litre mixture contains juice and water in the ratio 4 : 1. How many litres of water must be added to make the ratio 5 : 4?", "o": ["44 litres", "24 litres", "22 litres", "200/9 litres"], "a": 2, "e": "Juice = 40 L, water = 10 L. Need 40 : (10 + x) = 5 : 4 → x = 40×4/5 − 10 = 22 L.", "qh": "50 लीटर के एक मिश्रण में जूस और पानी का अनुपात 4 : 1 है। अनुपात 5 : 4 करने के लिए इसमें कितने लीटर पानी मिलाना होगा?", "oh": ["44 litres", "24 litres", "22 litres", "200/9 litres"], "eh": "जूस = 40 L, पानी = 10 L। 40 : (10 + x) = 5 : 4 → x = 40×4/5 − 10 = 22 L।", "level": "medium"}, {"s": "Mathematics", "t": "Percentage", "q": "Out of a monthly income, 25% goes to the family, 20% of the rest to household bills and 10% of the balance to a recurring deposit. The amount left is ₹37,800. Find the monthly income.", "o": ["₹72,000", "₹87,500", "₹69,000", "₹70,000"], "a": 3, "e": "Left = S × 75/100 × 80/100 × 90/100 = 0.54 S = ₹37,800 → S = ₹70,000.", "qh": "मासिक आय का 25% परिवार को, बाकी का 20% घर के बिलों में और बची रकम का 10% आवर्ती जमा (RD) में जाता है। बची रकम ₹37,800 है। मासिक आय बताइए।", "oh": ["₹72,000", "₹87,500", "₹69,000", "₹70,000"], "eh": "बचा = S × 75/100 × 80/100 × 90/100 = 0.54 S = ₹37,800 → S = ₹70,000।", "level": "easy"}, {"s": "Mathematics", "t": "Trigonometry", "q": "Find the value of sec 60° × cos 60°.", "o": ["1/2", "1", "2", "-1"], "a": 1, "e": "Put standard values: sec 60° = 2, cos 60° = 1/2 → value = 1.", "qh": "sec 60° × cos 60° का मान ज्ञात कीजिए।", "oh": ["1/2", "1", "2", "-1"], "eh": "मानक मान रखें: sec 60° = 2, cos 60° = 1/2 → मान = 1।", "level": "easy"}, {"s": "Mathematics", "t": "Profit and Loss", "q": "By selling 30 notebooks, a trader gains the selling price of 6 notebooks. What is his gain percentage?", "o": ["50%", "25%", "20%", "30%"], "a": 1, "e": "Gain = SP of 6, so CP of 30 = SP of 24. Gain % = 6/24 × 100 = 25%.", "qh": "30 कॉपियाँ बेचकर एक व्यापारी को 6 कॉपियाँ के विक्रय मूल्य के बराबर लाभ होता है। उसका लाभ प्रतिशत क्या है?", "oh": ["50%", "25%", "20%", "30%"], "eh": "लाभ = 6 का विक्रय मूल्य, इसलिए 30 का क्रय मूल्य = 24 का विक्रय मूल्य। लाभ % = 6/24 × 100 = 25%।", "level": "medium"}, {"s": "Mathematics", "t": "Simplification", "q": "Simplify: 2 1/2 + 3 3/4 − 4 1/4", "o": ["2", "2.5", "5/3", "3"], "a": 0, "e": "Convert to improper fractions: 5/2, 15/4, 17/4. Working step by step gives 2.", "qh": "सरल कीजिए: 2 1/2 + 3 3/4 − 4 1/4", "oh": ["2", "2.5", "5/3", "3"], "eh": "मिश्र भिन्नों को साधारण भिन्न में बदलें: 5/2, 15/4, 17/4। क्रम से हल करने पर 2।", "level": "easy"}, {"s": "Mathematics", "t": "Number System", "q": "If the number 9*6641 is divisible by 9, what is the digit in place of *?", "o": ["3", "9", "1", "6"], "a": 2, "e": "Rule: sum of digits divisible by 9. Only * = 1 works: 916641 ÷ 9 = 101849.", "qh": "अगर संख्या 9*6641 पूरी तरह 9 से विभाज्य है, तो * की जगह कौन-सा अंक है?", "oh": ["3", "9", "1", "6"], "eh": "नियम: अंकों का योग 9 से विभाज्य। केवल * = 1 सही बैठता है: 916641 ÷ 9 = 101849।", "level": "medium"}, {"s": "Mathematics", "t": "Average and Statistics", "q": "The average of 5 consecutive odd numbers is 47. What is the smallest of them?", "o": ["41", "51", "52", "43"], "a": 3, "e": "The average is the middle number 47; there are 2 numbers on each side with gap 2 → smallest = 43.", "qh": "5 लगातार विषम संख्याओं का औसत 47 है। उनमें सबसे छोटी संख्या कौन-सी है?", "oh": ["41", "51", "52", "43"], "eh": "औसत ही बीच वाली संख्या 47 है; दोनों ओर 2 संख्याएँ, अंतर 2 → उत्तर = 43।", "level": "easy"}, {"s": "Mathematics", "t": "Algebra", "q": "The sum of 3 consecutive natural numbers is 111. What is the smallest of them?", "o": ["35", "36", "37", "38"], "a": 1, "e": "Middle value = 111/3 = 37; numbers: 36, 37, 38; smallest = 36.", "qh": "3 क्रमागत प्राकृत संख्याओं का योग 111 है। इनमें सबसे छोटी संख्या कौन-सी है?", "oh": ["35", "36", "37", "38"], "eh": "बीच का मान = 111/3 = 37; संख्याएँ: 36, 37, 38; उत्तर = 36।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Calendar and Clock", "q": "What is the angle between the hour hand and the minute hand of a clock at 10:30?", "o": ["140°", "120°", "135°", "142.5°"], "a": 2, "e": "Angle = |30H − 5.5M| = |30×10 − 5.5×30| = 135° → smaller angle = 135°.", "qh": "10:30 बजे घड़ी की घंटे और मिनट की सुई के बीच कितना कोण होगा?", "oh": ["140°", "120°", "135°", "142.5°"], "eh": "कोण = |30H − 5.5M| = |30×10 − 5.5×30| = 135° → छोटा कोण = 135°।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nOOO, SQQ, WSS, AUU, ?", "o": ["GWW", "EWW", "EXW", "FWW"], "a": 1, "e": "Letter positions move by +4, +2, +2 (for 1st, 2nd, 3rd letters). So ? = EWW.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nOOO, SQQ, WSS, AUU, ?", "oh": ["GWW", "EWW", "EXW", "FWW"], "eh": "अक्षरों की स्थिति +4, +2, +2 से बदलती है (पहले, दूसरे, तीसरे अक्षर के लिए)। इसलिए ? = EWW।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Data Sufficiency", "q": "Question: What is the present age of Rahul?\nStatement I: Rahul will be 12 years old after 5 years.\nStatement II: Amit is 8 years old.\nWhich of the following is correct?", "o": ["The data in both statements together is not sufficient", "The data in both statements I and II together is needed", "The data in statement I alone is sufficient", "The data in either statement I alone or statement II alone is sufficient"], "a": 2, "e": "Statement I alone fixes the age; II alone does not.", "qh": "प्रश्न: राहुल की अभी की आयु क्या है?\nकथन I: 5 साल बाद राहुल की आयु 12 साल होगी।\nकथन II: अमित की आयु 8 साल है।\nनीचे दिए विकल्पों में से कौन-सा सही है?", "oh": ["दोनों कथन मिलकर भी काफ़ी नहीं हैं", "दोनों कथन I और II साथ में चाहिए", "केवल कथन I का आँकड़ा काफ़ी है", "अकेले कथन I या अकेले कथन II, कोई भी काफ़ी है"], "eh": "अकेला कथन I आयु तय कर देता है; अकेला II नहीं।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nVQW : WRA :: RBX : ?", "o": ["BCS", "SCB", "QAT", "SCC"], "a": 1, "e": "Each letter moves +1, +1, +4 in order. RBX → SCB.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nVQW : WRA :: RBX : ?", "oh": ["BCS", "SCB", "QAT", "SCC"], "eh": "हर अक्षर क्रम से +1, +1, +4 खिसकता है। RBX → SCB।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\n7, 16, 34, 70, 142, ?", "o": ["289", "282", "286", "287"], "a": 2, "e": "Rule: ×2 then +2. So ? = 286.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\n7, 16, 34, 70, 142, ?", "oh": ["289", "282", "286", "287"], "eh": "नियम: ×2 फिर +2। इसलिए ? = 286।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language:\n'bright water book' is written as 'fe mo bo',\n'green bright old' is written as 'bo xi ze',\n'water is green' is written as 'mo xi pu',\nWhat is the code for 'water'?", "o": ["bo", "fe", "xi", "mo"], "a": 3, "e": "Compare the sentences: common words and common codes match. This gives 'water' = 'mo'.", "qh": "एक कोड भाषा में:\n'bright water book' को 'fe mo bo' लिखा जाता है,\n'green bright old' को 'bo xi ze' लिखा जाता है,\n'water is green' को 'mo xi pu' लिखा जाता है,\n'water' का कोड क्या है?", "oh": ["bo", "fe", "xi", "mo"], "eh": "वाक्यों की तुलना करें: साझा शब्द और साझा कोड आपस में मिलते हैं। इससे 'water' = 'mo' मिलता है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["HIKM", "MNPQ", "KLNO", "NOQR"], "a": 0, "e": "In MNPQ, KLNO, NOQR the gaps are +1, +2, +1; in HIKM they are +1, +2, +2.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["HIKM", "MNPQ", "KLNO", "NOQR"], "eh": "MNPQ, KLNO, NOQR में अंतर +1, +2, +1 है; HIKM में +1, +2, +2 है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "The following questions are based on the five three-digit numbers given below.\n247   849   459   269   564\nIf the first and the third digits of each number are interchanged, what will be the sum of the digits of the largest number so formed?", "o": ["20", "17", "15", "18"], "a": 1, "e": "After swapping: 742, 948, 954, 962, 465. Largest = 962; digit sum = 17.", "qh": "नीचे दी गई पाँच तीन-अंकीय संख्याओं के आधार पर प्रश्न का उत्तर दीजिए।\n247   849   459   269   564\nअगर हर संख्या के पहले और तीसरे अंक आपस में बदल दिए जाएँ, तो बनी हुई सबसे बड़ी संख्या के अंकों का योग क्या होगा?", "oh": ["20", "17", "15", "18"], "eh": "अदला-बदली के बाद: 742, 948, 954, 962, 465। सबसे बड़ी = 962; अंकों का योग = 17।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\n3 4 7 E 8 H R H 5 2 4 7 A I 8 $ F O 6 & M 3\nHow many letters are there in the arrangement, each of which is immediately followed by a number but NOT immediately preceded by a symbol?", "o": ["5", "4", "3", "6"], "a": 1, "e": "Matching places: 7E8, RH5, AI8, FO6 → 4.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\n3 4 7 E 8 H R H 5 2 4 7 A I 8 $ F O 6 & M 3\nइस क्रम में ऐसे कितने अक्षर हैं, जिनके ठीक बाद एक संख्या है, पर ठीक पहले चिह्न नहीं है?", "oh": ["5", "4", "3", "6"], "eh": "शर्त पूरी करने वाले स्थान: 7E8, RH5, AI8, FO6 → 4।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["89", "103", "111", "67"], "a": 2, "e": "All except 111 are prime numbers.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["89", "103", "111", "67"], "eh": "111 को छोड़कर सभी अभाज्य संख्याएँ हैं।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "'A # B' means 'A is the daughter of B'; 'A − B' means 'A is the mother of B'; 'A ÷ B' means 'A is the husband of B'; 'A + B' means 'A is the wife of B'. If D − W ÷ N − G, how is D related to G?", "o": ["Grandmother", "Mother-in-law", "Daughter", "Sister-in-law"], "a": 0, "e": "Decode: D is the mother of W; W is the husband of N; N is the mother of G. So D is the grandmother of G.", "qh": "'A # B' का अर्थ है 'A, B की बेटी है'; 'A − B' का अर्थ है 'A, B की माँ है'; 'A ÷ B' का अर्थ है 'A, B का पति है'; 'A + B' का अर्थ है 'A, B की पत्नी है'। अगर D − W ÷ N − G, तो D का G से क्या संबंध है?", "oh": ["दादी/नानी", "सास", "बेटी", "साली/ननद/भाभी"], "eh": "अर्थ निकालें: D, W की माँ; W, N का पति; N, G की माँ। इसलिए D, G की दादी/नानी है।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nBE, FI, JM, NQ, ?", "o": ["RT", "RU", "RW", "TU"], "a": 1, "e": "Letter positions move by +4, +4 (for 1st, 2nd letters). So ? = RU.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nBE, FI, JM, NQ, ?", "oh": ["RT", "RU", "RW", "TU"], "eh": "अक्षरों की स्थिति +4, +4 से बदलती है (पहले, दूसरे अक्षर के लिए)। इसलिए ? = RU।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "Geeta is facing North-East. Geeta turns 45° anticlockwise, then 270° clockwise, then 90° clockwise. Which direction is Geeta facing now?", "o": ["East", "West", "North", "South"], "a": 2, "e": "Net turn = 315° (clockwise 315°). From North-East this gives North.", "qh": "गीता का मुँह उत्तर-पूर्व की ओर है। गीता 45° वामावर्त, फिर 270° दक्षिणावर्त, फिर 90° दक्षिणावर्त घूमता/घूमती है। अब उसका मुँह किस दिशा में है?", "oh": ["पूर्व", "पश्चिम", "उत्तर", "दक्षिण"], "eh": "कुल घुमाव = 315°। उत्तर-पूर्व से यह उत्तर देता है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Odd One Out", "q": "Three of the following four options are alike in a certain way and one is different. Select the odd one.", "o": ["Shimla", "Manali", "Jaisalmer", "Ooty"], "a": 2, "e": "Jaisalmer is a desert town; the others are hill stations.", "qh": "नीचे दिए गए चार विकल्पों में से तीन किसी तरह एक जैसे हैं और एक अलग है। अलग वाला चुनिए।", "oh": ["शिमला", "मनाली", "जैसलमेर", "ऊटी"], "eh": "जैसलमेर रेगिस्तानी शहर है; बाकी पहाड़ी जगहें हैं।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Series", "q": "What should come in place of the question mark (?) in the given series?\nG7Z, J12X, M17V, P22T, ?", "o": ["S29R", "S26R", "T27R", "S27R"], "a": 3, "e": "First letter +3; number: add 5; last letter -2. So ? = S27R.", "qh": "दी गई शृंखला में प्रश्न-चिह्न (?) की जगह क्या आएगा?\nG7Z, J12X, M17V, P22T, ?", "oh": ["S29R", "S26R", "T27R", "S27R"], "eh": "पहला अक्षर +3; संख्या: 5 जोड़ें; आखिरी अक्षर -2। इसलिए ? = S27R।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Ranking", "q": "In a class of 68 students, Arjun ranks 40th from the top. What is Arjun's rank from the bottom?", "o": ["28", "31", "30", "29"], "a": 3, "e": "Rank from bottom = 68 − 40 + 1 = 29.", "qh": "68 छात्रों की कक्षा में अर्जुन का स्थान ऊपर से 40वाँ है। नीचे से उसका स्थान क्या है?", "oh": ["28", "31", "30", "29"], "eh": "नीचे से स्थान = 68 − 40 + 1 = 29।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Symbol Series", "q": "Study the following arrangement carefully and answer the question.\n© 2 $ B 6 % 1 G 4 # & A 2 P 8 5 8 7 3 2 @ ©\nHow many letters are there in the arrangement, each of which is immediately followed by a number but NOT immediately preceded by a symbol?", "o": ["2", "3", "5", "4"], "a": 0, "e": "Matching places: 1G4, 2P8 → 2.", "qh": "नीचे दिए गए क्रम को ध्यान से पढ़कर प्रश्न का उत्तर दीजिए।\n© 2 $ B 6 % 1 G 4 # & A 2 P 8 5 8 7 3 2 @ ©\nइस क्रम में ऐसे कितने अक्षर हैं, जिनके ठीक बाद एक संख्या है, पर ठीक पहले चिह्न नहीं है?", "oh": ["2", "3", "5", "4"], "eh": "शर्त पूरी करने वाले स्थान: 1G4, 2P8 → 2।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Puzzle", "q": "7 boxes Q, S, W, Y, R, P and V are kept one above the other (not necessarily in this order).\nBox Q is placed somewhere above box W.\nExactly 3 boxes are placed between boxes S and Y.\nBox S is 2nd from the bottom.\nExactly 1 box is placed between boxes R and P.\nBox P is neither at the top nor at the bottom.\nExactly 5 boxes are placed between boxes W and V.\nExactly 1 box is placed between boxes W and R.\nHow many boxes are placed above box R?", "o": ["4", "7", "5", "3"], "a": 0, "e": "Only one order fits (bottom to top): W S R Q P Y V. Answer: 4.", "qh": "7 डिब्बे Q, S, W, Y, R, P और V एक के ऊपर एक रखे हैं (ज़रूरी नहीं कि इसी क्रम में)।\nडिब्बा Q, डिब्बे W से कहीं ऊपर रखा है।\nडिब्बे S और Y के बीच ठीक 3 डिब्बे रखे हैं।\nडिब्बा S नीचे से 2वें स्थान पर है।\nडिब्बे R और P के बीच ठीक 1 डिब्बे रखे हैं।\nडिब्बा P न सबसे ऊपर है, न सबसे नीचे।\nडिब्बे W और V के बीच ठीक 5 डिब्बे रखे हैं।\nडिब्बे W और R के बीच ठीक 1 डिब्बे रखे हैं।\nडिब्बे R के ऊपर कितने डिब्बे रखे हैं?", "oh": ["4", "7", "5", "3"], "eh": "केवल एक क्रम बैठता है (नीचे से ऊपर): W S R Q P Y V। उत्तर: 4।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Blood Relations", "q": "'A $ B' means 'A is the son of B'; 'A # B' means 'A is the sister of B'; 'A @ B' means 'A is the mother of B'; 'A × B' means 'A is the daughter of B'. If P × J @ W $ B, how is P related to B?", "o": ["Daughter-in-law", "Daughter", "Wife", "Granddaughter"], "a": 1, "e": "Decode: P is the daughter of J; J is the mother of W; W is the son of B. So P is the daughter of B.", "qh": "'A $ B' का अर्थ है 'A, B का बेटा है'; 'A # B' का अर्थ है 'A, B की बहन है'; 'A @ B' का अर्थ है 'A, B की माँ है'; 'A × B' का अर्थ है 'A, B की बेटी है'। अगर P × J @ W $ B, तो P का B से क्या संबंध है?", "oh": ["बहू", "बेटी", "पत्नी", "पोती/नातिन"], "eh": "अर्थ निकालें: P, J की बेटी; J, W की माँ; W, B का बेटा। इसलिए P, B की बेटी है।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "If '+' means '×', '−' means '÷', '×' means '−', '÷' means '+', then what is the value of the following expression?\n17 ÷ 21 + 4 ÷ 3 = ?", "o": ["208", "114", "106", "104"], "a": 3, "e": "Replace the signs: 17 + 21 × 4 + 3 = 104 (using BODMAS).", "qh": "अगर '+' का मतलब '×', '−' का मतलब '÷', '×' का मतलब '−', '÷' का मतलब '+' हो, तो नीचे दिए व्यंजक का मान क्या होगा?\n17 ÷ 21 + 4 ÷ 3 = ?", "oh": ["208", "114", "106", "104"], "eh": "चिह्न बदलें: 17 + 21 × 4 + 3 = 104 (BODMAS से)।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "L, G, S, R and D are sitting in a row, all facing North.\nS sits second to the right of G.\nD sits immediately to the right of G.\nG and D sit next to each other.\nL is not an immediate neighbour of D.\nExactly 1 person sits between S and R.\nD does not sit at either end.\nWho sits exactly in the middle of the row?", "o": ["S", "D", "R", "G"], "a": 0, "e": "Only one order fits all clues (left to right): G D S L R. Answer: S.", "qh": "L, G, S, R और D एक पंक्ति में उत्तर की ओर मुँह करके बैठे हैं।\nS, G के दाईं ओर दूसरे स्थान पर बैठा है।\nD, G के ठीक दाईं ओर बैठा है।\nG और D पास-पास बैठे हैं।\nL, D का ठीक पड़ोसी नहीं है।\nS और R के बीच ठीक 1 व्यक्ति बैठे हैं।\nD किसी भी छोर पर नहीं बैठा है।\nपंक्ति के ठीक बीच में कौन बैठा है?", "oh": ["S", "D", "R", "G"], "eh": "सभी शर्तों पर केवल एक क्रम बैठता है (बाएँ से दाएँ): G D S L R। उत्तर: S।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Syllogism", "q": "Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatements:\nNo bricks are lamps.\nNo lamps are tables.\nConclusions:\nI. No lamps are bricks.\nII. No tables are bricks.", "o": ["Neither I nor II follows", "Both I and II follow", "Only conclusion II follows", "Only conclusion I follows"], "a": 3, "e": "Conclusion I is true in every possible diagram; II is not.", "qh": "दिए गए कथनों और निष्कर्षों को ध्यान से पढ़िए। कथनों को सही मानते हुए, भले ही वे आम जानकारी से अलग लगें, तय कीजिए कि कौन-सा/से निष्कर्ष कथनों से तर्क के आधार पर निकलता/निकलते है/हैं।\nकथन:\nकोई भी ईंटें लैंप नहीं है।\nकोई भी लैंप मेज़ें नहीं है।\nनिष्कर्ष:\nI. कोई भी लैंप ईंटें नहीं है।\nII. कोई भी मेज़ें ईंटें नहीं है।", "oh": ["न I सही है, न II", "I और II दोनों सही हैं", "केवल निष्कर्ष II सही है", "केवल निष्कर्ष I सही है"], "eh": "निष्कर्ष I हर संभव आरेख में सही है; II नहीं।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Directions", "q": "X is 4 m West of S. W is 9 m East of X. T is 8 m South of W. Y is 3 m West of T. In which direction is Y with respect to S?", "o": ["South-East", "North-West", "North-East", "South-West"], "a": 0, "e": "Taking S at (0, 0), Y is at (2, -8) → South-East.", "qh": "X, S से 4 m पश्चिम में है। W, X से 9 m पूर्व में है। T, W से 8 m दक्षिण में है। Y, T से 3 m पश्चिम में है। Y, S से किस दिशा में है?", "oh": ["दक्षिण-पूर्व", "उत्तर-पश्चिम", "उत्तर-पूर्व", "दक्षिण-पश्चिम"], "eh": "S को (0, 0) मानें तो Y (2, -8) पर है → दक्षिण-पूर्व।", "level": "tough"}, {"s": "General Intelligence and Reasoning", "t": "Mathematical Operations", "q": "If '+' means '−', '−' means '÷', '×' means '+', '÷' means '×', then what is the value of the following expression?\n9 × 27 × 3 ÷ 9 = ?", "o": ["65", "60", "73", "63"], "a": 3, "e": "Replace the signs: 9 + 27 + 3 × 9 = 63 (using BODMAS).", "qh": "अगर '+' का मतलब '−', '−' का मतलब '÷', '×' का मतलब '+', '÷' का मतलब '×' हो, तो नीचे दिए व्यंजक का मान क्या होगा?\n9 × 27 × 3 ÷ 9 = ?", "oh": ["65", "60", "73", "63"], "eh": "चिह्न बदलें: 9 + 27 + 3 × 9 = 63 (BODMAS से)।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\n13 : 169 :: 8 : ?", "o": ["65", "80", "72", "64"], "a": 3, "e": "Rule: x → x². 13 → 169, so 8 → 64.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\n13 : 169 :: 8 : ?", "oh": ["65", "80", "72", "64"], "eh": "नियम: x → x²। 13 → 169, इसलिए 8 → 64।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Coding-Decoding", "q": "In a certain code language, 'CHAIR' is coded as 39. How will 'RIVER' be coded in that language?", "o": ["73", "70", "72", "77"], "a": 2, "e": "Code = sum of letter positions (A = 1, B = 2, …). For RIVER: 72.", "qh": "एक कोड भाषा में 'CHAIR' को 39 लिखा जाता है। उसी भाषा में 'RIVER' को कैसे लिखा जाएगा?", "oh": ["73", "70", "72", "77"], "eh": "कोड = अक्षरों की स्थितियों का योग (A = 1, B = 2, …)। RIVER के लिए: 72।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Analogy", "q": "Select the option that is related to the third term in the same way as the second term is related to the first term.\nPainter : Brush :: Writer : ?", "o": ["Book", "Paper", "Pen", "Story"], "a": 2, "e": "Relation: 'tool'. Painter – Brush, so Writer – Pen.", "qh": "वह विकल्प चुनिए जो तीसरे पद से उसी तरह जुड़ा है, जैसे दूसरा पद पहले पद से जुड़ा है।\nचित्रकार : ब्रश :: लेखक : ?", "oh": ["किताब", "कागज़", "पेन", "कहानी"], "eh": "संबंध: 'औज़ार'। चित्रकार – ब्रश, इसलिए लेखक – पेन।", "level": "easy"}, {"s": "General Intelligence and Reasoning", "t": "Digit Operations", "q": "Study the following series of digits and answer the question.\n5 6 1 5 5 3 5 6 3 1 1 3 6 4 1 3 6 3 2 8 8 2 7 6 5\nHow many 5s are there, each of which is immediately preceded by an odd digit and immediately followed by an even digit?", "o": ["4", "3", "2", "1"], "a": 3, "e": "Matching groups: 3 5 6 → 1.", "qh": "नीचे दी गई अंकों की शृंखला पढ़कर प्रश्न का उत्तर दीजिए।\n5 6 1 5 5 3 5 6 3 1 1 3 6 4 1 3 6 3 2 8 8 2 7 6 5\nऐसे कितने 5 हैं, जिनके ठीक पहले विषम अंक और ठीक बाद सम अंक है?", "oh": ["4", "3", "2", "1"], "eh": "शर्त पूरी करने वाले समूह: 3 5 6 → 1।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Seating Arrangement", "q": "S, B, M, C, G and H are sitting around a circular table, all facing the centre.\nM sits second to the right of H.\nG sits second to the left of C.\nM sits immediately to the left of B.\nC is an immediate neighbour of M.\nWho sits to the immediate right of G?", "o": ["H", "M", "S", "C"], "a": 0, "e": "Only one arrangement fits. Going to the right (anticlockwise) from G: G → H → C → M → B → S. Answer: H.", "qh": "S, B, M, C, G और H एक गोल मेज़ के चारों ओर केंद्र की ओर मुँह करके बैठे हैं।\nM, H के दाईं ओर दूसरे स्थान पर बैठा है।\nG, C के बाईं ओर दूसरे स्थान पर बैठा है।\nM, B के ठीक बाईं ओर बैठा है।\nC, M का ठीक पड़ोसी है।\nG के ठीक दाईं ओर कौन बैठा है?", "oh": ["H", "M", "S", "C"], "eh": "केवल एक व्यवस्था बैठती है। G से दाईं ओर (घड़ी की उलटी दिशा में) चलें: G → H → C → M → B → S। उत्तर: H।", "level": "medium"}, {"s": "General Intelligence and Reasoning", "t": "Syllogism", "q": "Read the given statements and conclusions carefully. Assuming that the information given in the statements is true, even if it appears to be at variance with commonly known facts, decide which of the given conclusions logically follow(s) from the statements.\nStatements:\nAll shoes are trees.\nSome trees are clocks.\nConclusions:\nI. No trees are shoes.\nII. Some trees are shoes.", "o": ["Only conclusion I follows", "Only conclusion II follows", "Both I and II follow", "Neither I nor II follows"], "a": 1, "e": "Conclusion II is true in every possible diagram; I is not.", "qh": "दिए गए कथनों और निष्कर्षों को ध्यान से पढ़िए। कथनों को सही मानते हुए, भले ही वे आम जानकारी से अलग लगें, तय कीजिए कि कौन-सा/से निष्कर्ष कथनों से तर्क के आधार पर निकलता/निकलते है/हैं।\nकथन:\nसभी जूते पेड़ हैं।\nकुछ पेड़ घड़ियाँ हैं।\nनिष्कर्ष:\nI. कोई भी पेड़ जूते नहीं है।\nII. कुछ पेड़ जूते हैं।", "oh": ["केवल निष्कर्ष I सही है", "केवल निष्कर्ष II सही है", "I और II दोनों सही हैं", "न I सही है, न II"], "eh": "निष्कर्ष II हर संभव आरेख में सही है; I नहीं।", "level": "easy"}]});
